PLACES = [
 {"s":"weekuri-lagoon","c":"beach","sec":False,"r":"sbd","ll":[-9.49109,118.95983],"img":"magnitude-6-1-earthquake-southwest-sumba",
  "n":{"id":"Danau Weekuri"},
  "en":{"n":"Weekuri Lagoon","t":"A saltwater lagoon cut off from the open ocean by a wall of coral rock. Waves push sea water through the cracks, so the pool stays clear, calm and turquoise. It is the most photographed spot in Southwest Sumba.","tip":"Go early on a weekday: weekends fill up with local families. Bring water shoes for the rocks."},
  "es":{"n":"Laguna Weekuri","t":"Una laguna de agua salada separada del océano por un muro de roca coralina. Las olas empujan el agua del mar por las grietas, así que la piscina se mantiene clara, tranquila y turquesa. Es el rincón más fotografiado del suroeste de Sumba.","tip":"Ve temprano y entre semana: los fines de semana se llena de familias locales. Lleva escarpines para las rocas."},
  "id":{"n":"Danau Weekuri","t":"Laguna air asin yang terpisah dari laut lepas oleh dinding batu karang. Ombak mendorong air laut lewat celah-celah batu, sehingga airnya tetap jernih, tenang dan berwarna toska. Tempat paling banyak difoto di Sumba Barat Daya.","tip":"Datang pagi pada hari kerja: akhir pekan ramai keluarga lokal. Bawa sepatu air untuk bebatuan."},
  "de":{"n":"Weekuri-Lagune","t":"Eine Salzwasserlagune, die durch eine Wand aus Korallenfels vom offenen Meer getrennt ist. Die Wellen drücken Meerwasser durch die Spalten, deshalb bleibt das Becken klar, ruhig und türkis. Der meistfotografierte Ort im Südwesten Sumbas.","tip":"Früh und unter der Woche kommen: Am Wochenende ist es voll mit einheimischen Familien. Wasserschuhe für die Felsen mitnehmen."},
  "fr":{"n":"Lagune de Weekuri","t":"Une lagune d'eau salée séparée de l'océan par un mur de roche corallienne. Les vagues poussent l'eau de mer à travers les fissures : le bassin reste clair, calme et turquoise. C'est le lieu le plus photographié du sud-ouest de Sumba.","tip":"Venez tôt en semaine : le week-end, les familles locales affluent. Prévoyez des chaussures d'eau pour les rochers."},
  "nl":{"n":"Weekuri-lagune","t":"Een zoutwaterlagune die door een wand van koraalrots van de open zee is gescheiden. De golven duwen zeewater door de spleten, zodat het water helder, rustig en turquoise blijft. De meest gefotografeerde plek van Zuidwest-Sumba.","tip":"Ga vroeg op een doordeweekse dag: in het weekend is het druk met lokale families. Neem waterschoenen mee voor de rotsen."}},

 {"s":"mandorak-beach","c":"beach","sec":False,"r":"sbd","ll":[-9.49908,118.95410],"img":None,
  "n":{"id":"Pantai Mandorak"},
  "en":{"n":"Mandorak Beach","t":"A tiny cove of white sand squeezed between two cliffs, a few minutes from Weekuri Lagoon. The Indian Ocean pounds the rocks at the entrance, so it is more for looking than swimming.","tip":"Combine it with Weekuri in one morning. Swim only on very calm days."},
  "es":{"n":"Playa Mandorak","t":"Una cala diminuta de arena blanca encajada entre dos acantilados, a pocos minutos de la laguna Weekuri. El Índico golpea las rocas de la entrada, así que es más para mirar que para bañarse.","tip":"Combínala con Weekuri en la misma mañana. Báñate solo en días muy tranquilos."},
  "id":{"n":"Pantai Mandorak","t":"Teluk kecil berpasir putih yang terjepit di antara dua tebing, beberapa menit dari Danau Weekuri. Ombak Samudra Hindia menghantam batu di mulut teluk, jadi lebih cocok untuk dinikmati daripada berenang.","tip":"Gabungkan dengan Weekuri dalam satu pagi. Berenanglah hanya saat laut sangat tenang."},
  "de":{"n":"Mandorak-Strand","t":"Eine winzige weiße Sandbucht zwischen zwei Klippen, wenige Minuten von der Weekuri-Lagune entfernt. Der Indische Ozean schlägt gegen die Felsen am Eingang, daher eher zum Schauen als zum Schwimmen.","tip":"Mit Weekuri an einem Vormittag verbinden. Nur an sehr ruhigen Tagen baden."},
  "fr":{"n":"Plage de Mandorak","t":"Une minuscule crique de sable blanc coincée entre deux falaises, à quelques minutes de la lagune de Weekuri. L'océan Indien frappe les rochers à l'entrée : on y vient surtout pour regarder.","tip":"À combiner avec Weekuri dans la même matinée. Ne vous baignez que par mer très calme."},
  "nl":{"n":"Mandorak-strand","t":"Een piepklein baaitje met wit zand tussen twee kliffen, een paar minuten van de Weekuri-lagune. De Indische Oceaan beukt op de rotsen bij de ingang, dus meer om te kijken dan om te zwemmen.","tip":"Combineer het met Weekuri op één ochtend. Zwem alleen bij heel kalme zee."}},

 {"s":"ratenggaro","c":"village","sec":False,"r":"sbd","ll":[-9.63019,119.00037],"img":"marapu-ikat-traditional-villages",
  "n":{"id":"Kampung Adat Ratenggaro"},
  "en":{"n":"Ratenggaro Village","t":"A traditional Kodi village of towering thatched roofs and stone megalithic tombs set right above the beach. The houses are homes and the tombs are sacred in the Marapu belief, so this is a place to visit slowly and respectfully.","tip":"Sign the guestbook and leave a donation. Ask before photographing people. Do not climb on tombs."},
  "es":{"n":"Aldea de Ratenggaro","t":"Una aldea tradicional de Kodi con tejados de paja altísimos y tumbas megalíticas de piedra justo encima de la playa. Las casas están habitadas y las tumbas son sagradas en la creencia marapu: es un lugar para visitar despacio y con respeto.","tip":"Firma el libro de visitas y deja un donativo. Pide permiso antes de fotografiar a la gente. No te subas a las tumbas."},
  "id":{"n":"Kampung Adat Ratenggaro","t":"Kampung adat Kodi dengan atap ilalang menjulang dan kubur batu megalitik tepat di atas pantai. Rumah-rumahnya dihuni dan kuburnya sakral dalam kepercayaan Marapu, jadi kunjungi dengan pelan dan hormat.","tip":"Isi buku tamu dan beri sumbangan. Minta izin sebelum memotret orang. Jangan naik ke atas kubur."},
  "de":{"n":"Dorf Ratenggaro","t":"Ein traditionelles Kodi-Dorf mit hoch aufragenden Strohdächern und megalithischen Steingräbern direkt über dem Strand. Die Häuser sind bewohnt und die Gräber im Marapu-Glauben heilig: ein Ort für einen ruhigen, respektvollen Besuch.","tip":"Ins Gästebuch eintragen und eine Spende geben. Vor dem Fotografieren von Menschen fragen. Nicht auf die Gräber steigen."},
  "fr":{"n":"Village de Ratenggaro","t":"Un village traditionnel de Kodi aux toits de chaume vertigineux et aux tombes mégalithiques en pierre, juste au-dessus de la plage. Les maisons sont habitées et les tombes sacrées dans la croyance marapu : on y vient lentement et avec respect.","tip":"Signez le livre d'or et laissez un don. Demandez avant de photographier les gens. Ne montez pas sur les tombes."},
  "nl":{"n":"Dorp Ratenggaro","t":"Een traditioneel Kodi-dorp met torenhoge rieten daken en megalithische stenen graven pal boven het strand. De huizen worden bewoond en de graven zijn heilig in het Marapu-geloof: bezoek het rustig en met respect.","tip":"Teken het gastenboek en laat een donatie achter. Vraag toestemming voor je mensen fotografeert. Klim niet op de graven."}},

 {"s":"wainyapu","c":"village","sec":True,"r":"sbd","ll":[-9.63099,119.00769],"img":None,
  "n":{"id":"Kampung Adat Wainyapu"},
  "en":{"n":"Wainyapu Village","t":"Ratenggaro's quieter neighbour, across the river mouth. It has one of the largest groups of stone tombs in Kodi and far fewer visitors, which makes it feel like stepping back in time.","tip":"Ask a local guide from Ratenggaro to take you across. Same rules: guestbook, donation, no climbing on tombs."},
  "es":{"n":"Aldea de Wainyapu","t":"La vecina tranquila de Ratenggaro, al otro lado de la desembocadura del río. Tiene uno de los mayores conjuntos de tumbas de piedra de Kodi y muchos menos visitantes: parece un viaje en el tiempo.","tip":"Pide a un guía local de Ratenggaro que te cruce. Mismas normas: libro de visitas, donativo y no subirse a las tumbas."},
  "id":{"n":"Kampung Adat Wainyapu","t":"Tetangga Ratenggaro yang lebih sepi, di seberang muara sungai. Di sini ada salah satu kelompok kubur batu terbesar di Kodi dengan pengunjung jauh lebih sedikit, seperti kembali ke masa lalu.","tip":"Minta pemandu lokal dari Ratenggaro mengantar menyeberang. Aturannya sama: buku tamu, sumbangan, jangan naik ke kubur."},
  "de":{"n":"Dorf Wainyapu","t":"Der ruhigere Nachbar von Ratenggaro, auf der anderen Seite der Flussmündung. Hier steht eine der größten Gruppen von Steingräbern in Kodi, mit weit weniger Besuchern: wie eine Zeitreise.","tip":"Einen lokalen Guide aus Ratenggaro bitten, Sie hinüberzubringen. Gleiche Regeln: Gästebuch, Spende, nicht auf Gräber steigen."},
  "fr":{"n":"Village de Wainyapu","t":"Le voisin plus discret de Ratenggaro, de l'autre côté de l'embouchure. Il abrite l'un des plus grands ensembles de tombes en pierre de Kodi, avec bien moins de visiteurs : un voyage dans le temps.","tip":"Demandez à un guide local de Ratenggaro de vous faire traverser. Mêmes règles : livre d'or, don, ne pas monter sur les tombes."},
  "nl":{"n":"Dorp Wainyapu","t":"De rustigere buur van Ratenggaro, aan de overkant van de riviermonding. Hier staat een van de grootste groepen stenen graven van Kodi, met veel minder bezoekers: een reis terug in de tijd.","tip":"Vraag een lokale gids uit Ratenggaro om je over te zetten. Dezelfde regels: gastenboek, donatie, niet op graven klimmen."}},

 {"s":"pero-beach","c":"beach","sec":True,"r":"sbd","ll":[-9.60598,118.98424],"img":None,
  "n":{"id":"Pantai Pero"},
  "en":{"n":"Pero Beach","t":"A working fishing village on the Kodi coast with wooden boats pulled up on the sand and a reef break that draws a handful of surfers. Few tourists stop here, and the sunsets face straight out to sea.","tip":"Come for sunset and buy grilled fish from the village. Surf only if you know reef breaks."},
  "es":{"n":"Playa de Pero","t":"Un pueblo pesquero en activo en la costa de Kodi, con barcas de madera varadas en la arena y una ola de arrecife que atrae a unos pocos surfistas. Casi ningún turista para aquí, y la puesta de sol cae justo sobre el mar.","tip":"Ven al atardecer y compra pescado a la brasa en el pueblo. Surfea solo si conoces las olas de arrecife."},
  "id":{"n":"Pantai Pero","t":"Kampung nelayan di pesisir Kodi dengan perahu kayu di atas pasir dan ombak karang yang menarik segelintir peselancar. Sedikit wisatawan mampir, dan matahari terbenam tepat di atas laut.","tip":"Datang saat senja dan beli ikan bakar dari warga. Berselancar hanya jika terbiasa dengan ombak karang."},
  "de":{"n":"Pero-Strand","t":"Ein aktives Fischerdorf an der Küste von Kodi, mit Holzbooten auf dem Sand und einer Riffwelle, die ein paar Surfer anzieht. Kaum Touristen halten hier, und die Sonne geht direkt über dem Meer unter.","tip":"Zum Sonnenuntergang kommen und gegrillten Fisch im Dorf kaufen. Nur surfen, wenn Sie Riffwellen kennen."},
  "fr":{"n":"Plage de Pero","t":"Un vrai village de pêcheurs sur la côte de Kodi, avec ses barques en bois tirées sur le sable et une vague de récif qui attire quelques surfeurs. Peu de touristes s'y arrêtent, et le soleil se couche face à la mer.","tip":"Venez au coucher du soleil et achetez du poisson grillé au village. Ne surfez que si vous connaissez les vagues de récif."},
  "nl":{"n":"Pero-strand","t":"Een echt vissersdorp aan de kust van Kodi, met houten boten op het zand en een rifgolf die een handvol surfers trekt. Weinig toeristen stoppen hier, en de zon gaat recht boven zee onder.","tip":"Kom bij zonsondergang en koop gegrilde vis in het dorp. Surf alleen als je rifgolven kent."}},

 {"s":"marosi-beach","c":"beach","sec":False,"r":"sb","ll":[-9.76237,119.31461],"img":None,
  "n":{"id":"Pantai Marosi"},
  "en":{"n":"Marosi Beach","t":"A long, wide stretch of pale sand on the Lamboya coast of West Sumba, backed by palms and fields. It feels endless and empty for most of the year.","tip":"Strong currents: swim only where locals do, and never alone. Bring shade, there is little of it."},
  "es":{"n":"Playa de Marosi","t":"Una playa larga y ancha de arena clara en la costa de Lamboya, en Sumba Occidental, con palmeras y campos detrás. Casi todo el año parece infinita y vacía.","tip":"Corrientes fuertes: báñate solo donde se bañan los locales y nunca solo. Lleva sombra, hay poca."},
  "id":{"n":"Pantai Marosi","t":"Pantai panjang dan lebar berpasir terang di pesisir Lamboya, Sumba Barat, dengan pohon kelapa dan sawah di belakangnya. Hampir sepanjang tahun terasa luas dan sepi.","tip":"Arus kuat: berenang hanya di tempat warga berenang dan jangan sendirian. Bawa peneduh, di sana jarang ada."},
  "de":{"n":"Marosi-Strand","t":"Ein langer, breiter Strand mit hellem Sand an der Küste von Lamboya in West-Sumba, mit Palmen und Feldern dahinter. Fast das ganze Jahr wirkt er endlos und leer.","tip":"Starke Strömungen: nur dort schwimmen, wo Einheimische schwimmen, und nie allein. Schatten mitbringen, es gibt kaum welchen."},
  "fr":{"n":"Plage de Marosi","t":"Une longue et large plage de sable clair sur la côte de Lamboya, dans l'ouest de Sumba, bordée de palmiers et de champs. Elle semble infinie et déserte presque toute l'année.","tip":"Courants forts : ne vous baignez que là où les habitants se baignent, jamais seul. Apportez de l'ombre, il y en a peu."},
  "nl":{"n":"Marosi-strand","t":"Een lang, breed strand met licht zand aan de kust van Lamboya in West-Sumba, met palmen en velden erachter. Het grootste deel van het jaar voelt het eindeloos en leeg.","tip":"Sterke stroming: zwem alleen waar de lokale bewoners zwemmen en nooit alleen. Neem schaduw mee, die is er nauwelijks."}},

 {"s":"lapopu-waterfall","c":"waterfall","sec":False,"r":"st","ll":[-9.67832,119.49298],"img":None,
  "n":{"id":"Air Terjun Lapopu"},
  "en":{"n":"Lapopu Waterfall","t":"One of Sumba's tallest waterfalls, tumbling down a series of rock terraces inside Matalawa National Park, on the border of West and Central Sumba. The pools at the bottom are cool and clear.","tip":"Best from April to July, when there is still water but the access road is dry. Pay the small park fee at the entrance."},
  "es":{"n":"Cascada de Lapopu","t":"Una de las cascadas más altas de Sumba, que cae por una serie de terrazas de roca dentro del Parque Nacional Matalawa, en el límite entre Sumba Occidental y Central. Las pozas de abajo son frescas y claras.","tip":"Mejor de abril a julio, cuando aún lleva agua pero la pista está seca. Paga la pequeña entrada del parque."},
  "id":{"n":"Air Terjun Lapopu","t":"Salah satu air terjun tertinggi di Sumba, mengalir menuruni teras-teras batu di dalam Taman Nasional Matalawa, di perbatasan Sumba Barat dan Sumba Tengah. Kolam di bawahnya sejuk dan jernih.","tip":"Paling bagus April sampai Juli, saat air masih ada tapi jalan sudah kering. Bayar tiket kecil taman nasional di pintu masuk."},
  "de":{"n":"Lapopu-Wasserfall","t":"Einer der höchsten Wasserfälle Sumbas, der über eine Reihe von Felsterrassen im Matalawa-Nationalpark fällt, an der Grenze zwischen West- und Zentral-Sumba. Die Becken unten sind kühl und klar.","tip":"Am besten von April bis Juli: noch Wasser, aber die Zufahrt ist trocken. Die kleine Parkgebühr am Eingang zahlen."},
  "fr":{"n":"Cascade de Lapopu","t":"L'une des plus hautes cascades de Sumba, qui dévale une série de terrasses rocheuses dans le parc national de Matalawa, entre l'ouest et le centre de l'île. Les bassins en contrebas sont frais et limpides.","tip":"Idéal d'avril à juillet : il reste de l'eau et la piste est sèche. Réglez le petit droit d'entrée du parc."},
  "nl":{"n":"Lapopu-waterval","t":"Een van de hoogste watervallen van Sumba, die over een reeks rotsterrassen stort in Nationaal Park Matalawa, op de grens van West- en Midden-Sumba. De poelen onderaan zijn koel en helder.","tip":"Het mooist van april tot juli: nog water, maar de toegangsweg is droog. Betaal de kleine parkentree bij de ingang."}},

 {"s":"matayangu-waterfall","c":"waterfall","sec":True,"r":"st","ll":[-9.67329,119.50470],"img":None,
  "n":{"id":"Air Terjun Matayangu"},
  "en":{"n":"Matayangu Waterfall","t":"A hidden waterfall deep in the forest of Matalawa National Park in Central Sumba, reached on foot along a jungle trail. Locals call it a sacred place, and it is one of the least visited sights on the island.","tip":"Go with a local guide and good shoes; the trail is slippery after rain. Start early and carry water."},
  "es":{"n":"Cascada de Matayangu","t":"Una cascada escondida en lo más profundo del bosque del Parque Nacional Matalawa, en Sumba Central, a la que se llega a pie por un sendero de selva. Los locales la consideran un lugar sagrado y es de los rincones menos visitados de la isla.","tip":"Ve con guía local y buen calzado: el sendero resbala después de llover. Sal temprano y lleva agua."},
  "id":{"n":"Air Terjun Matayangu","t":"Air terjun tersembunyi jauh di dalam hutan Taman Nasional Matalawa, Sumba Tengah, dicapai dengan berjalan kaki lewat jalur hutan. Warga menganggapnya tempat sakral, dan termasuk yang paling jarang dikunjungi di pulau ini.","tip":"Pergi bersama pemandu lokal dan sepatu yang baik; jalurnya licin setelah hujan. Berangkat pagi dan bawa air."},
  "de":{"n":"Matayangu-Wasserfall","t":"Ein versteckter Wasserfall tief im Wald des Matalawa-Nationalparks in Zentral-Sumba, nur zu Fuß über einen Dschungelpfad erreichbar. Einheimische betrachten ihn als heiligen Ort, und er gehört zu den am wenigsten besuchten Zielen der Insel.","tip":"Mit lokalem Guide und gutem Schuhwerk gehen; der Pfad ist nach Regen rutschig. Früh starten und Wasser mitnehmen."},
  "fr":{"n":"Cascade de Matayangu","t":"Une cascade cachée au cœur de la forêt du parc national de Matalawa, au centre de Sumba, accessible à pied par un sentier de jungle. Les habitants la tiennent pour un lieu sacré, et c'est l'un des sites les moins visités de l'île.","tip":"Partez avec un guide local et de bonnes chaussures : le sentier glisse après la pluie. Partez tôt, avec de l'eau."},
  "nl":{"n":"Matayangu-waterval","t":"Een verborgen waterval diep in het bos van Nationaal Park Matalawa in Midden-Sumba, alleen te voet bereikbaar via een junglepad. De lokale bewoners zien het als een heilige plek, en het is een van de minst bezochte plekken van het eiland.","tip":"Ga met een lokale gids en goede schoenen; het pad is glad na regen. Vertrek vroeg en neem water mee."}},

 {"s":"tarung-village","c":"village","sec":False,"r":"sb","ll":[-9.63234,119.40754],"img":None,
  "n":{"id":"Kampung Tarung"},
  "en":{"n":"Tarung Village","t":"A hilltop traditional village in the middle of Waikabubak, the capital of West Sumba. High-roofed clan houses and stone tombs sit a short walk from the town's shops, and it remains an important centre of Marapu ceremonies.","tip":"Easy to visit if you are staying in Waikabubak. Dress modestly and ask before entering a house."},
  "es":{"n":"Aldea de Tarung","t":"Una aldea tradicional en lo alto de una colina en pleno Waikabubak, la capital de Sumba Occidental. Las casas de clan de tejado alto y las tumbas de piedra quedan a un paseo de las tiendas, y sigue siendo un centro importante de ceremonias marapu.","tip":"Fácil de visitar si duermes en Waikabubak. Viste con discreción y pide permiso antes de entrar en una casa."},
  "id":{"n":"Kampung Tarung","t":"Kampung adat di atas bukit di tengah Waikabubak, ibu kota Sumba Barat. Rumah suku beratap tinggi dan kubur batu hanya beberapa langkah dari pertokoan, dan tetap menjadi pusat penting upacara Marapu.","tip":"Mudah dikunjungi jika menginap di Waikabubak. Berpakaian sopan dan minta izin sebelum masuk rumah."},
  "de":{"n":"Dorf Tarung","t":"Ein traditionelles Dorf auf einem Hügel mitten in Waikabubak, der Hauptstadt von West-Sumba. Clanhäuser mit hohen Dächern und Steingräber liegen nur ein paar Schritte von den Geschäften entfernt, und es ist bis heute ein wichtiges Zentrum der Marapu-Zeremonien.","tip":"Leicht zu besuchen, wenn Sie in Waikabubak übernachten. Dezent kleiden und vor dem Betreten eines Hauses fragen."},
  "fr":{"n":"Village de Tarung","t":"Un village traditionnel perché sur une colline au cœur de Waikabubak, chef-lieu de l'ouest de Sumba. Maisons claniques à haut toit et tombes en pierre sont à deux pas des boutiques, et le lieu reste un centre important des cérémonies marapu.","tip":"Facile à visiter si vous dormez à Waikabubak. Tenue correcte et demandez avant d'entrer dans une maison."},
  "nl":{"n":"Dorp Tarung","t":"Een traditioneel dorp op een heuvel midden in Waikabubak, de hoofdstad van West-Sumba. Clanhuizen met hoge daken en stenen graven liggen op loopafstand van de winkels, en het is nog altijd een belangrijk centrum van Marapu-ceremonies.","tip":"Makkelijk te bezoeken als je in Waikabubak slaapt. Kleed je bedekt en vraag toestemming voor je een huis binnengaat."}},

 {"s":"pasola-wanokaka","c":"culture","sec":False,"r":"sb","ll":[-9.72054,119.45254],"img":"pasola-explained",
  "n":{"id":"Pasola Wanokaka"},
  "en":{"n":"Pasola field, Wanokaka","t":"The open field where Wanokaka holds the Pasola, a ritual contest in which riders throw blunt wooden spears at each other on horseback. It takes place once a year around February or March in Kodi, Lamboya, Wanokaka and Gaura, on dates set by Marapu elders.","tip":"Dates are only confirmed a few days ahead. Watch from where locals tell you, well away from the horses."},
  "es":{"n":"Campo de la Pasola, Wanokaka","t":"La explanada donde Wanokaka celebra la Pasola, un combate ritual en el que jinetes a caballo se lanzan lanzas de madera sin punta. Se celebra una vez al año hacia febrero o marzo en Kodi, Lamboya, Wanokaka y Gaura, en fechas que fijan los ancianos marapu.","tip":"Las fechas se confirman pocos días antes. Mira desde donde te indiquen los locales, lejos de los caballos."},
  "id":{"n":"Lapangan Pasola Wanokaka","t":"Lapangan tempat Wanokaka menggelar Pasola, ritual adu ketangkasan berkuda dengan saling melempar lembing kayu tumpul. Diadakan setahun sekali sekitar Februari atau Maret di Kodi, Lamboya, Wanokaka dan Gaura, pada tanggal yang ditentukan tetua Marapu.","tip":"Tanggal baru pasti beberapa hari sebelumnya. Menonton dari tempat yang ditunjuk warga, jauh dari kuda."},
  "de":{"n":"Pasola-Feld, Wanokaka","t":"Das offene Feld, auf dem Wanokaka die Pasola austrägt: einen rituellen Wettkampf, bei dem Reiter stumpfe Holzspeere aufeinander werfen. Sie findet einmal im Jahr um Februar oder März in Kodi, Lamboya, Wanokaka und Gaura statt, an Tagen, die die Marapu-Ältesten festlegen.","tip":"Die Termine werden erst wenige Tage vorher bestätigt. Von dort zuschauen, wo Einheimische es zeigen, weit weg von den Pferden."},
  "fr":{"n":"Terrain de la Pasola, Wanokaka","t":"Le grand terrain où Wanokaka organise la Pasola, joute rituelle où des cavaliers se lancent des javelots en bois émoussés. Elle a lieu une fois par an vers février ou mars à Kodi, Lamboya, Wanokaka et Gaura, à des dates fixées par les anciens marapu.","tip":"Les dates ne sont confirmées que quelques jours avant. Regardez depuis l'endroit indiqué par les habitants, loin des chevaux."},
  "nl":{"n":"Pasola-veld, Wanokaka","t":"Het open veld waar Wanokaka de Pasola houdt: een ritueel gevecht waarbij ruiters stompe houten speren naar elkaar gooien. Het vindt eens per jaar plaats rond februari of maart in Kodi, Lamboya, Wanokaka en Gaura, op data die de Marapu-ouderen bepalen.","tip":"De data worden pas een paar dagen vooraf bevestigd. Kijk vanaf de plek die lokale bewoners aanwijzen, ver van de paarden."}},

 {"s":"wairinding-hill","c":"viewpoint","sec":False,"r":"stim","ll":[-9.67946,120.10005],"img":"where-to-stay-in-sumba",
  "n":{"id":"Bukit Wairinding"},
  "en":{"n":"Wairinding Hill","t":"Rolling grass hills beside the main road west of Waingapu, green in the rainy season and gold in the dry months. It is the classic East Sumba sunset view, often with children from the nearby village offering to guide you.","tip":"Arrive an hour before sunset. A small tip for the kids who guide you is customary; sweets are not a good idea."},
  "es":{"n":"Colina de Wairinding","t":"Colinas de hierba onduladas junto a la carretera principal al oeste de Waingapu, verdes en época de lluvias y doradas en los meses secos. Es el atardecer clásico de Sumba Oriental, a menudo con niños del pueblo cercano que se ofrecen a guiarte.","tip":"Llega una hora antes de la puesta de sol. Se suele dar una pequeña propina a los niños que te guían; los caramelos no son buena idea."},
  "id":{"n":"Bukit Wairinding","t":"Perbukitan rumput bergelombang di samping jalan utama sebelah barat Waingapu, hijau saat musim hujan dan keemasan saat kemarau. Ini pemandangan senja klasik Sumba Timur, sering ditemani anak-anak kampung yang menawarkan diri jadi pemandu.","tip":"Datang satu jam sebelum matahari terbenam. Tip kecil untuk anak-anak pemandu sudah biasa; permen bukan ide baik."},
  "de":{"n":"Wairinding-Hügel","t":"Sanfte Grashügel an der Hauptstraße westlich von Waingapu, grün in der Regenzeit und golden in den trockenen Monaten. Der klassische Sonnenuntergang Ost-Sumbas, oft mit Kindern aus dem Dorf, die sich als Führer anbieten.","tip":"Eine Stunde vor Sonnenuntergang da sein. Ein kleines Trinkgeld für die Kinder ist üblich; Süßigkeiten sind keine gute Idee."},
  "fr":{"n":"Colline de Wairinding","t":"Des collines herbeuses ondulantes au bord de la route principale à l'ouest de Waingapu, vertes à la saison des pluies, dorées en saison sèche. C'est le coucher de soleil classique de l'est de Sumba, souvent avec des enfants du village voisin qui proposent de vous guider.","tip":"Arrivez une heure avant le coucher du soleil. Un petit pourboire aux enfants guides est d'usage ; les bonbons, non."},
  "nl":{"n":"Wairinding-heuvel","t":"Glooiende grasheuvels langs de hoofdweg ten westen van Waingapu, groen in het regenseizoen en goudkleurig in de droge maanden. Hét zonsondergangsuitzicht van Oost-Sumba, vaak met kinderen uit het dorp die aanbieden je te gidsen.","tip":"Kom een uur voor zonsondergang. Een kleine fooi voor de kinderen is gebruikelijk; snoep is geen goed idee."}},

 {"s":"brotherhood-hill","c":"viewpoint","sec":True,"r":"stim","ll":[-9.67398,120.29623],"img":"east-sumba-first-customary-land-certificate",
  "n":{"id":"Bukit Persaudaraan"},
  "en":{"n":"Brotherhood Hill","t":"Bukit Persaudaraan, a ridge of savanna hills just outside Waingapu with wide views over valleys, rice fields and the sea. Far fewer people come here than to Wairinding, and it is only a short drive from town.","tip":"Perfect for a quick sunrise or sunset if you only have one evening in Waingapu."},
  "es":{"n":"Colina de la Hermandad","t":"Bukit Persaudaraan, una cresta de colinas de sabana a las afueras de Waingapu con vistas amplias de valles, arrozales y el mar. Viene mucha menos gente que a Wairinding y está a pocos minutos del pueblo.","tip":"Perfecta para un amanecer o atardecer rápido si solo tienes una tarde en Waingapu."},
  "id":{"n":"Bukit Persaudaraan","t":"Punggungan bukit sabana di pinggir Waingapu dengan pemandangan luas ke lembah, sawah dan laut. Jauh lebih sepi daripada Wairinding, dan hanya perjalanan singkat dari kota.","tip":"Cocok untuk matahari terbit atau terbenam singkat jika hanya punya satu sore di Waingapu."},
  "de":{"n":"Bruderschaftshügel","t":"Bukit Persaudaraan, ein Kamm aus Savannenhügeln direkt vor Waingapu, mit weitem Blick über Täler, Reisfelder und das Meer. Viel weniger Besucher als in Wairinding und nur eine kurze Fahrt von der Stadt.","tip":"Ideal für einen schnellen Sonnenauf- oder -untergang, wenn Sie nur einen Abend in Waingapu haben."},
  "fr":{"n":"Colline de la Fraternité","t":"Bukit Persaudaraan, une crête de collines de savane aux portes de Waingapu, avec une vue large sur les vallées, les rizières et la mer. Bien moins fréquentée que Wairinding et à quelques minutes de la ville.","tip":"Parfait pour un lever ou coucher de soleil express si vous n'avez qu'une soirée à Waingapu."},
  "nl":{"n":"Broederschapsheuvel","t":"Bukit Persaudaraan, een rug van savanneheuvels net buiten Waingapu met wijds uitzicht over dalen, rijstvelden en de zee. Veel minder druk dan Wairinding en maar een kort ritje van de stad.","tip":"Perfect voor een snelle zonsopkomst of -ondergang als je maar één avond in Waingapu hebt."}},

 {"s":"prailiu-village","c":"village","sec":False,"r":"stim","ll":[-9.65913,120.27668],"img":None,
  "n":{"id":"Kampung Raja Prailiu"},
  "en":{"n":"Prailiu Royal Village","t":"A traditional royal village inside Waingapu, known for its hand-woven ikat. Weavers often work in front of the houses, and you can see how the threads are tied and dyed with natural colours before weaving.","tip":"Buying directly from the weavers is the best way to support them. Real hand-made ikat takes months, so prices reflect that."},
  "es":{"n":"Aldea real de Prailiu","t":"Una aldea real tradicional dentro de Waingapu, famosa por su ikat tejido a mano. Las tejedoras suelen trabajar delante de las casas y se ve cómo se atan y tiñen los hilos con colores naturales antes de tejer.","tip":"Comprar directamente a las tejedoras es la mejor forma de apoyarlas. Un ikat hecho a mano lleva meses, y el precio lo refleja."},
  "id":{"n":"Kampung Raja Prailiu","t":"Kampung raja tradisional di dalam kota Waingapu, terkenal dengan tenun ikat buatan tangan. Para penenun sering bekerja di depan rumah, dan Anda bisa melihat benang diikat dan dicelup pewarna alami sebelum ditenun.","tip":"Membeli langsung dari penenun adalah cara terbaik mendukung mereka. Tenun ikat asli butuh berbulan-bulan, jadi harganya sesuai."},
  "de":{"n":"Königsdorf Prailiu","t":"Ein traditionelles Königsdorf mitten in Waingapu, bekannt für handgewebten Ikat. Die Weberinnen arbeiten oft vor den Häusern, und man sieht, wie die Fäden gebunden und mit Naturfarben gefärbt werden.","tip":"Direkt bei den Weberinnen kaufen unterstützt sie am meisten. Echter handgemachter Ikat dauert Monate, das spiegelt der Preis."},
  "fr":{"n":"Village royal de Prailiu","t":"Un village royal traditionnel en pleine ville de Waingapu, réputé pour son ikat tissé à la main. Les tisserandes travaillent souvent devant les maisons : on voit les fils noués et teints aux couleurs naturelles avant le tissage.","tip":"Acheter directement aux tisserandes est la meilleure façon de les soutenir. Un vrai ikat fait main demande des mois, d'où son prix."},
  "nl":{"n":"Koninklijk dorp Prailiu","t":"Een traditioneel koninklijk dorp midden in Waingapu, bekend om zijn handgeweven ikat. De weefsters werken vaak voor hun huizen, en je ziet hoe de draden worden afgebonden en met natuurlijke kleuren geverfd.","tip":"Rechtstreeks bij de weefsters kopen steunt hen het meest. Echte handgemaakte ikat kost maanden werk, en dat zie je in de prijs."}},

 {"s":"walakiri-beach","c":"beach","sec":False,"r":"stim","ll":[-9.62861,120.42751],"img":"beaches-lagoons-waterfalls",
  "n":{"id":"Pantai Walakiri"},
  "en":{"n":"Walakiri Beach","t":"A shallow beach east of Waingapu where small mangrove trees stand in the water. At sunset and low tide their twisted shapes turn into silhouettes, the famous \"dancing trees\" of Sumba.","tip":"Check the tide: the trees look best at low tide around sunset. Watch your step, the sea floor has sharp shells."},
  "es":{"n":"Playa de Walakiri","t":"Una playa poco profunda al este de Waingapu donde pequeños manglares crecen dentro del agua. Al atardecer y con marea baja sus formas retorcidas se vuelven siluetas: los famosos \"árboles que bailan\" de Sumba.","tip":"Mira la marea: los árboles lucen más con marea baja al atardecer. Cuidado al pisar, hay conchas afiladas."},
  "id":{"n":"Pantai Walakiri","t":"Pantai dangkal di timur Waingapu tempat pohon bakau kecil tumbuh di dalam air. Saat senja dan air surut, bentuknya yang meliuk menjadi siluet, \"pohon menari\" yang terkenal dari Sumba.","tip":"Cek pasang surut: pohon paling indah saat surut menjelang senja. Hati-hati melangkah, ada cangkang tajam."},
  "de":{"n":"Walakiri-Strand","t":"Ein flacher Strand östlich von Waingapu, an dem kleine Mangroven im Wasser stehen. Bei Sonnenuntergang und Ebbe werden ihre verdrehten Formen zu Silhouetten: die berühmten \"tanzenden Bäume\" Sumbas.","tip":"Gezeiten prüfen: Am schönsten bei Ebbe zum Sonnenuntergang. Vorsicht, am Boden liegen scharfe Muscheln."},
  "fr":{"n":"Plage de Walakiri","t":"Une plage peu profonde à l'est de Waingapu où de petits palétuviers poussent dans l'eau. Au coucher du soleil et à marée basse, leurs formes tordues deviennent des silhouettes : les fameux « arbres qui dansent » de Sumba.","tip":"Vérifiez la marée : les arbres sont plus beaux à marée basse au coucher du soleil. Attention aux coquillages coupants."},
  "nl":{"n":"Walakiri-strand","t":"Een ondiep strand ten oosten van Waingapu waar kleine mangrovebomen in het water staan. Bij zonsondergang en eb worden hun kronkelige vormen silhouetten: de beroemde \"dansende bomen\" van Sumba.","tip":"Check het getij: de bomen zijn het mooist bij eb rond zonsondergang. Let op waar je loopt, er liggen scherpe schelpen."}},

 {"s":"puru-kambera","c":"beach","sec":False,"r":"stim","ll":[-9.48493,120.13265],"img":"illegal-gold-panning-east-sumba-paberiwai",
  "n":{"id":"Pantai dan Sabana Puru Kambera"},
  "en":{"n":"Puru Kambera","t":"Where the savanna of East Sumba runs straight into the sea, north-west of Waingapu. Horses graze among the dry grass and lone trees, and the beach is long, quiet and good for swimming on calm days.","tip":"Keep your distance from the horses; they belong to local families. Late afternoon light is the best."},
  "es":{"n":"Puru Kambera","t":"Donde la sabana de Sumba Oriental llega directamente al mar, al noroeste de Waingapu. Los caballos pastan entre la hierba seca y árboles solitarios, y la playa es larga, tranquila y buena para bañarse en días de calma.","tip":"Mantén la distancia con los caballos: son de familias locales. La mejor luz es a última hora de la tarde."},
  "id":{"n":"Puru Kambera","t":"Tempat sabana Sumba Timur bertemu langsung dengan laut, di barat laut Waingapu. Kuda merumput di antara rumput kering dan pohon-pohon tunggal, dan pantainya panjang, tenang dan enak untuk berenang saat laut tenang.","tip":"Jaga jarak dari kuda; kuda-kuda itu milik keluarga setempat. Cahaya sore hari paling bagus."},
  "de":{"n":"Puru Kambera","t":"Hier geht die Savanne Ost-Sumbas direkt ins Meer über, nordwestlich von Waingapu. Pferde grasen zwischen trockenem Gras und einzelnen Bäumen, und der Strand ist lang, ruhig und an ruhigen Tagen gut zum Baden.","tip":"Abstand zu den Pferden halten, sie gehören einheimischen Familien. Das Licht am späten Nachmittag ist am schönsten."},
  "fr":{"n":"Puru Kambera","t":"Là où la savane de l'est de Sumba plonge directement dans la mer, au nord-ouest de Waingapu. Des chevaux paissent entre herbes sèches et arbres isolés, et la plage est longue, calme et agréable par mer d'huile.","tip":"Gardez vos distances avec les chevaux, ils appartiennent à des familles locales. La plus belle lumière est en fin d'après-midi."},
  "nl":{"n":"Puru Kambera","t":"Waar de savanne van Oost-Sumba recht de zee in loopt, ten noordwesten van Waingapu. Paarden grazen tussen droog gras en losse bomen, en het strand is lang, rustig en bij kalme zee goed om te zwemmen.","tip":"Houd afstand van de paarden; ze zijn van lokale families. Het licht laat in de middag is het mooist."}},

 {"s":"praiyawang-rende","c":"village","sec":True,"r":"stim","ll":[-9.93560,120.66996],"img":None,
  "n":{"id":"Praiyawang, Rende"},
  "en":{"n":"Praiyawang, Rende","t":"The old royal village of Rende in south-east Sumba, famous for some of the largest carved stone tombs on the island and for fine ikat. It is a long drive from Waingapu, which keeps it calm.","tip":"Plan a full day and combine it with Waimarang Waterfall. Ask permission before photographing the tombs."},
  "es":{"n":"Praiyawang, Rende","t":"La antigua aldea real de Rende, en el sureste de Sumba, famosa por algunas de las tumbas de piedra tallada más grandes de la isla y por su ikat fino. Está a muchos kilómetros de Waingapu, lo que la mantiene tranquila.","tip":"Reserva el día entero y combínala con la cascada de Waimarang. Pide permiso antes de fotografiar las tumbas."},
  "id":{"n":"Praiyawang, Rende","t":"Kampung raja lama Rende di tenggara Sumba, terkenal dengan beberapa kubur batu berukir terbesar di pulau ini dan tenun ikat yang halus. Jaraknya jauh dari Waingapu, sehingga suasananya tenang.","tip":"Sediakan satu hari penuh dan gabungkan dengan Air Terjun Waimarang. Minta izin sebelum memotret kubur."},
  "de":{"n":"Praiyawang, Rende","t":"Das alte Königsdorf von Rende im Südosten Sumbas, berühmt für einige der größten verzierten Steingräber der Insel und feinen Ikat. Es liegt weit von Waingapu entfernt, deshalb ist es ruhig.","tip":"Einen ganzen Tag einplanen und mit dem Waimarang-Wasserfall verbinden. Vor dem Fotografieren der Gräber fragen."},
  "fr":{"n":"Praiyawang, Rende","t":"L'ancien village royal de Rende, au sud-est de Sumba, célèbre pour certaines des plus grandes tombes en pierre sculptée de l'île et pour son ikat raffiné. Loin de Waingapu, il reste paisible.","tip":"Prévoyez une journée et combinez avec la cascade de Waimarang. Demandez avant de photographier les tombes."},
  "nl":{"n":"Praiyawang, Rende","t":"Het oude koninklijke dorp van Rende in het zuidoosten van Sumba, beroemd om enkele van de grootste bewerkte stenen graven van het eiland en om fijne ikat. Het ligt ver van Waingapu, en dat houdt het rustig.","tip":"Trek een hele dag uit en combineer met de Waimarang-waterval. Vraag toestemming voor je de graven fotografeert."}},

 {"s":"waimarang-waterfall","c":"waterfall","sec":True,"r":"stim","ll":[-9.96871,120.60280],"img":None,
  "n":{"id":"Air Terjun Waimarang"},
  "en":{"n":"Waimarang Waterfall","t":"A waterfall that drops into a round, jade-green pool surrounded by rock walls, in the Rindi area of East Sumba. The last part is a steep walk down, and the reward is a swim in a natural amphitheatre.","tip":"The path is steep and loose: good shoes, no flip-flops. Go in the dry season and avoid it after heavy rain."},
  "es":{"n":"Cascada de Waimarang","t":"Una cascada que cae en una poza redonda verde jade rodeada de paredes de roca, en la zona de Rindi, en Sumba Oriental. El último tramo es una bajada empinada, y el premio es un baño en un anfiteatro natural.","tip":"El camino es empinado y suelto: buen calzado, nada de chanclas. Ve en época seca y evítala tras lluvias fuertes."},
  "id":{"n":"Air Terjun Waimarang","t":"Air terjun yang jatuh ke kolam bundar berwarna hijau giok dikelilingi dinding batu, di wilayah Rindi, Sumba Timur. Bagian terakhir berupa jalan menurun yang curam, dan hadiahnya berenang di amfiteater alami.","tip":"Jalurnya curam dan berkerikil: pakai sepatu yang baik, bukan sandal jepit. Datang saat kemarau dan hindari setelah hujan lebat."},
  "de":{"n":"Waimarang-Wasserfall","t":"Ein Wasserfall, der in ein rundes, jadegrünes Becken zwischen Felswänden stürzt, im Gebiet Rindi in Ost-Sumba. Das letzte Stück geht steil bergab, die Belohnung ist ein Bad in einem natürlichen Amphitheater.","tip":"Der Weg ist steil und lose: gute Schuhe, keine Flip-Flops. In der Trockenzeit gehen, nach starkem Regen meiden."},
  "fr":{"n":"Cascade de Waimarang","t":"Une cascade qui tombe dans un bassin rond vert jade cerné de parois rocheuses, dans la région de Rindi, à l'est de Sumba. La fin du chemin est une descente raide, récompensée par une baignade dans un amphithéâtre naturel.","tip":"Le sentier est raide et instable : bonnes chaussures, pas de tongs. En saison sèche, et à éviter après de fortes pluies."},
  "nl":{"n":"Waimarang-waterval","t":"Een waterval die in een ronde, jadegroene poel tussen rotswanden valt, in het gebied Rindi in Oost-Sumba. Het laatste stuk is een steile afdaling, en de beloning is een duik in een natuurlijk amfitheater.","tip":"Het pad is steil en los: goede schoenen, geen slippers. Ga in het droge seizoen en vermijd het na zware regen."}},

 {"s":"tarimbang-bay","c":"beach","sec":True,"r":"stim","ll":[-9.95831,119.95917],"img":None,
  "n":{"id":"Pantai Tarimbang"},
  "en":{"n":"Tarimbang Bay","t":"A remote bay on the south coast of East Sumba, reached by a long, winding road through the hills. A wide beach, a consistent surf break and almost nobody else make it one of the island's real escapes.","tip":"Fill up on fuel and cash before leaving Waingapu; there is very little on the way. A 4x4 or a driver who knows the road helps."},
  "es":{"n":"Bahía de Tarimbang","t":"Una bahía remota en la costa sur de Sumba Oriental, a la que se llega por una carretera larga y sinuosa entre colinas. Una playa amplia, una ola constante y casi nadie más la convierten en una de las verdaderas escapadas de la isla.","tip":"Llena el depósito y saca efectivo antes de salir de Waingapu; por el camino hay muy poco. Ayuda un 4x4 o un conductor que conozca la ruta."},
  "id":{"n":"Pantai Tarimbang","t":"Teluk terpencil di pantai selatan Sumba Timur, dicapai lewat jalan panjang berkelok di antara perbukitan. Pantai yang luas, ombak yang konsisten dan hampir tanpa orang lain menjadikannya pelarian sejati di pulau ini.","tip":"Isi bensin dan siapkan uang tunai sebelum meninggalkan Waingapu; di jalan hampir tidak ada apa-apa. Mobil 4x4 atau sopir yang tahu jalan sangat membantu."},
  "de":{"n":"Tarimbang-Bucht","t":"Eine abgelegene Bucht an der Südküste Ost-Sumbas, erreichbar über eine lange, kurvige Straße durch die Hügel. Ein breiter Strand, eine verlässliche Surfwelle und fast niemand sonst machen sie zu einem echten Rückzugsort.","tip":"Vor der Abfahrt in Waingapu tanken und Bargeld holen; unterwegs gibt es sehr wenig. Ein Allrad oder ein ortskundiger Fahrer hilft."},
  "fr":{"n":"Baie de Tarimbang","t":"Une baie isolée sur la côte sud de l'est de Sumba, au bout d'une longue route sinueuse à travers les collines. Une large plage, une vague régulière et presque personne : l'une des vraies échappées de l'île.","tip":"Faites le plein et retirez du liquide avant de quitter Waingapu ; il n'y a presque rien en route. Un 4x4 ou un chauffeur qui connaît la route aide."},
  "nl":{"n":"Tarimbang-baai","t":"Een afgelegen baai aan de zuidkust van Oost-Sumba, bereikbaar via een lange, kronkelende weg door de heuvels. Een breed strand, een constante surfgolf en bijna niemand anders maken het een echte ontsnapping.","tip":"Tank vol en neem contant geld mee voor je uit Waingapu vertrekt; onderweg is er weinig. Een 4x4 of een chauffeur die de weg kent helpt."}},

 {"s":"wanggameti","c":"viewpoint","sec":True,"r":"stim","ll":[-10.11644,120.23623],"img":None,
  "n":{"id":"Wanggameti, Taman Nasional Matalawa"},
  "en":{"n":"Wanggameti","t":"The highlands around Mount Wanggameti, the highest point of Sumba, inside Matalawa National Park. Cool forest, mountain villages and endemic birds such as the Sumba hornbill make it a different side of the island that very few visitors see.","tip":"Only with a local guide and a sturdy vehicle. Bring a warm layer: nights are cool up here."},
  "es":{"n":"Wanggameti","t":"Las tierras altas alrededor del monte Wanggameti, el punto más alto de Sumba, dentro del Parque Nacional Matalawa. Bosque fresco, aldeas de montaña y aves endémicas como el cálao de Sumba: otra cara de la isla que muy pocos visitantes conocen.","tip":"Solo con guía local y un vehículo robusto. Lleva algo de abrigo: las noches son frescas allí arriba."},
  "id":{"n":"Wanggameti","t":"Dataran tinggi di sekitar Gunung Wanggameti, titik tertinggi di Sumba, di dalam Taman Nasional Matalawa. Hutan yang sejuk, kampung pegunungan dan burung endemik seperti julang Sumba menunjukkan sisi lain pulau ini yang jarang dilihat pengunjung.","tip":"Hanya bersama pemandu lokal dan kendaraan yang kuat. Bawa jaket: malam di sana dingin."},
  "de":{"n":"Wanggameti","t":"Das Hochland um den Berg Wanggameti, den höchsten Punkt Sumbas, im Matalawa-Nationalpark. Kühler Wald, Bergdörfer und endemische Vögel wie der Sumba-Hornvogel zeigen eine Seite der Insel, die nur sehr wenige Besucher sehen.","tip":"Nur mit lokalem Guide und robustem Fahrzeug. Eine warme Schicht mitnehmen: Die Nächte sind hier oben kühl."},
  "fr":{"n":"Wanggameti","t":"Les hautes terres autour du mont Wanggameti, point culminant de Sumba, dans le parc national de Matalawa. Forêt fraîche, villages de montagne et oiseaux endémiques comme le calao de Sumba : une autre facette de l'île que très peu de visiteurs découvrent.","tip":"Uniquement avec un guide local et un véhicule solide. Prévoyez une petite laine : les nuits sont fraîches là-haut."},
  "nl":{"n":"Wanggameti","t":"Het hoogland rond de berg Wanggameti, het hoogste punt van Sumba, in Nationaal Park Matalawa. Koel bos, bergdorpen en endemische vogels zoals de Sumba-neushoornvogel tonen een kant van het eiland die maar weinig bezoekers zien.","tip":"Alleen met een lokale gids en een stevig voertuig. Neem een warme laag mee: de nachten zijn hier koel."}},
]

